import { RemediationAssessment } from './remediation-assessment';
import { RemediationDetailsItemVulnerabilityState } from './remediation-details-item-vulnerability-state';
import { RemediationItemDetailsVulnerableComponent } from './remediation-item-details-vulnerable-component';
import { RemediationItemMuteState } from './remediation-item-mute-state';
import { RemediationProgress } from './remediation-progress';
import { TrackingLink } from './tracking-link';
/**
 * Detailed information of a remediation item for a security problem.
 */
export interface RemediationDetailsItem {
    assessment?: RemediationAssessment;
    entityIds?: string[];
    firstAffectedTimestamp?: number;
    id?: string;
    muteState?: RemediationItemMuteState;
    name?: string;
    remediationProgress?: RemediationProgress;
    resolvedTimestamp?: number;
    trackingLink?: TrackingLink;
    vulnerabilityState?: RemediationDetailsItemVulnerabilityState;
    /**
     * A list of vulnerable components of the remediation item.
     *
     * A vulnerable component is what causes the security problem.
     */
    vulnerableComponents?: RemediationItemDetailsVulnerableComponent[];
}
